package com.yeyamo_mobile.api.culture_service.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="culture_challenge_submissions")public class CultureChallengeSubmission{public enum Status{PENDING_MODERATION,ACCEPTED,REJECTED,WITHDRAWN}@Id private UUID id;@Column(name="user_id",nullable=false)private String userId;@Column(name="challenge_id",nullable=false)private UUID challengeId;@Column(name="post_id")private UUID postId;@Column(name="culture_contribution_id")private UUID cultureContributionId;@Column(name="media_ids")private String mediaIds;@Column(name="language_code",length=35)private String languageCode;@Column(columnDefinition="TEXT")private String translation;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(name="moderation_reason")private String moderationReason;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="withdrawn_at")private Instant withdrawnAt;protected CultureChallengeSubmission(){}public static CultureChallengeSubmission create(String user,UUID challenge,UUID post,UUID contribution,List<UUID>media,String language,String translation,boolean moderation,String reason){if(post==null&&contribution==null&&(media==null||media.isEmpty()))throw new IllegalArgumentException("A postId, cultureContributionId or mediaId is required");CultureChallengeSubmission s=new CultureChallengeSubmission();s.id=UUID.randomUUID();s.userId=user;s.challengeId=challenge;s.postId=post;s.cultureContributionId=contribution;s.mediaIds=media==null?null:media.stream().map(UUID::toString).reduce((a,b)->a+","+b).orElse(null);s.languageCode=language;s.translation=translation;s.status=moderation?Status.PENDING_MODERATION:Status.ACCEPTED;s.moderationReason=reason;s.createdAt=Instant.now();return s;}public void withdraw(String actor){if(!userId.equals(actor))throw new SecurityException("Submission owner mismatch");status=Status.WITHDRAWN;withdrawnAt=Instant.now();}public UUID getId(){return id;}public String getUserId(){return userId;}public UUID getChallengeId(){return challengeId;}public UUID getPostId(){return postId;}public UUID getCultureContributionId(){return cultureContributionId;}public List<UUID> getMediaIds(){return mediaIds==null?List.of():Arrays.stream(mediaIds.split(",")).map(UUID::fromString).toList();}public String getLanguageCode(){return languageCode;}public String getTranslation(){return translation;}public Status getStatus(){return status;}public String getModerationReason(){return moderationReason;}public Instant getCreatedAt(){return createdAt;}public Instant getWithdrawnAt(){return withdrawnAt;}}
